export function lookupKnowledgeDeep(text) {
  if (!text) return null;
  const t = String(text).toLowerCase();
  let best = null, bestScore = 0;
  for (const e of KNOWLEDGE_DEEP) {
    let score = 0;
    for (const k of e.keys) {
      const nk = String(k).toLowerCase();
      const idx = t.indexOf(nk);
      if (idx < 0) continue;
      score += nk.length * nk.length + 4 + (1 - idx / Math.max(1, t.length)) * 3;
    }
    if (score > bestScore) { bestScore = score; best = e; }
  }
  return bestScore > 0 ? best : null;
}
export function countKnowledgeDeep() { return KNOWLEDGE_DEEP.length; }
